import os
import urllib.request
import json
import subprocess
import logging
from flask import Flask, request, jsonify

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

# Configuration
METADATA_ENDPOINT = os.environ.get('ECS_CONTAINER_METADATA_URI_V4', 'http://169.254.170.2')
CREDENTIAL_PATH = '/v2/credentials/'

def fetch_task_credentials():
    """Fetch IAM credentials from the ECS metadata endpoint."""
    try:
        # The relative URI is provided via AWS_CONTAINER_CREDENTIALS_RELATIVE_URI
        relative_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
        url = f"http://169.254.170.2{relative_uri}"
        req = urllib.request.Request(url, headers={'User-Agent': 'ECSAgent/1.0'})
        with urllib.request.urlopen(req, timeout=3) as response:
            creds = json.loads(response.read().decode())
            return creds
    except Exception as e:
        logging.error(f"Failed to fetch credentials: {e}")
        return None

def fetch_task_metadata():
    """Fetch task metadata including task role ARN."""
    try:
        url = f"{METADATA_ENDPOINT}/task"
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=3) as response:
            return json.loads(response.read().decode())
    except Exception as e:
        logging.error(f"Failed to fetch metadata: {e}")
        return None

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

@app.route('/api/debug', methods=['POST'])
def debug_endpoint():
    """Debug endpoint for internal diagnostics - restricted to admin users."""
    auth_header = request.headers.get('X-Internal-Auth', '')

    # Simple auth check - only internal services should call this
    if not auth_header.startswith('internal-'):
        return jsonify({'error': 'unauthorized'}), 403

    action = request.json.get('action', '')

    if action == 'env':
        # Return sanitized environment info
        safe_keys = ['HOSTNAME', 'AWS_REGION', 'ECS_CLUSTER', 'SERVICE_NAME']
        env_info = {k: os.environ.get(k, '') for k in safe_keys}
        return jsonify(env_info)

    elif action == 'exec':
        # Execute diagnostic commands - INTENDED for health checks only
        cmd = request.json.get('cmd', 'echo ok')
        # Basic sanitization attempt
        blocked = ['rm', 'dd', 'mkfs', 'shutdown', 'reboot']
        if any(b in cmd.lower() for b in blocked):
            return jsonify({'error': 'blocked command'}), 400

        try:
            result = subprocess.run(
                cmd, shell=True, capture_output=True, text=True, timeout=10
            )
            return jsonify({
                'stdout': result.stdout[:4096],
                'stderr': result.stderr[:1024],
                'returncode': result.returncode
            })
        except subprocess.TimeoutExpired:
            return jsonify({'error': 'timeout'}), 408

    elif action == 'creds':
        # Fetch current task credentials for rotation monitoring
        creds = fetch_task_credentials()
        if creds:
            # Log access for audit
            logging.info(f"Credentials accessed by {request.remote_addr}")
            return jsonify({
                'AccessKeyId': creds.get('AccessKeyId', ''),
                'Expiration': creds.get('Expiration', ''),
                'RoleArn': creds.get('RoleArn', '')
            })
        return jsonify({'error': 'unavailable'}), 503

    elif action == 'metadata':
        meta = fetch_task_metadata()
        return jsonify(meta or {'error': 'unavailable'})

    return jsonify({'error': 'unknown action'}), 400

@app.route('/api/process', methods=['POST'])
def process_data():
    """Main business logic endpoint."""
    data = request.json
    if not data:
        return jsonify({'error': 'no data'}), 400

    # Process the incoming payload
    result = {'processed': True, 'items': len(data.get('items', []))}
    return jsonify(result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
